"""ZIP Builder — packages a ProjectScaffold into a downloadable ZIP archive."""

from __future__ import annotations

import logging
import zipfile
from pathlib import Path

from app.domain.entities.project_scaffold import ProjectScaffold
from app.domain.paths import safe_relative_path, slugify
from app.domain.ports.archive_port import ArchivePort

logger = logging.getLogger(__name__)


class ZipBuilder(ArchivePort):
    """Builds a ZIP archive from a ProjectScaffold's generated files."""

    async def build(self, scaffold: ProjectScaffold, output_dir: Path) -> Path:
        """
        Create a ZIP file containing all generated scaffold files.

        The file on disk is named after the (server-generated) document id so
        two projects can never overwrite each other. The project name only
        appears *inside* the archive, slugified. Files whose path is absolute
        or escapes the project folder are skipped.
        """
        output_dir.mkdir(parents=True, exist_ok=True)
        root = slugify(scaffold.project_name, default="generated-project")
        zip_path = (
            output_dir / f"{slugify(scaffold.document_id, default='scaffold')}.zip"
        )

        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
            readme = (
                f"# {root}\n\n"
                "Generated by Structify.\n\n"
                f"## Directory Structure\n\n```\n{scaffold.directory_tree}\n```\n"
            )
            zf.writestr(f"{root}/README.md", readme)

            for gen_file in scaffold.files:
                rel = safe_relative_path(gen_file.path)
                if rel is None or rel == "README.md":
                    logger.warning(
                        "Skipping unsafe or reserved scaffold path %r", gen_file.path
                    )
                    continue
                zf.writestr(f"{root}/{rel}", gen_file.content)

        return zip_path
